"use client";

import { useEffect, useRef, useState } from "react";
import { returningApi } from "../api/returning.api";
import type { ClaimStart, ClaimTransition, DocumentQuestion, MaskedCandidates, PassportProof, ReturningHistory } from "../types";

/** The server selects the next verification stage. Client state never grants access. */
export function useReturningClaim() {
  const [transition, setTransition] = useState<ClaimTransition | null>(null);
  const [candidates, setCandidates] = useState<MaskedCandidates | null>(null);
  const [history, setHistory] = useState<ReturningHistory | null>(null);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string>();
  const [resendAt, setResendAt] = useState(0);
  const [otpSent, setOtpSent] = useState(false);
  const method = useRef<ClaimStart["method"]>("phone");
  const groupToken = useRef<string | undefined>(undefined);
  const active = useRef<AbortController | null>(null);
  useEffect(() => () => active.current?.abort(), []);

  const run = async (operation: (signal: AbortSignal) => Promise<void>) => {
    if (active.current) return;
    const controller = new AbortController();
    active.current = controller;
    setPending(true);
    setError(undefined);
    try { await operation(controller.signal); }
    catch (cause) {
      if (!controller.signal.aborted) setError(typeof cause === "object" && cause !== null && "message" in cause && typeof cause.message === "string" ? cause.message : "We could not complete this step. Please retry or upload current documents.");
    } finally {
      active.current = null;
      if (!controller.signal.aborted) setPending(false);
    }
  };

  const accept = async (next: ClaimTransition, signal: AbortSignal): Promise<void> => {
    if (signal.aborted) return;
    setTransition(next);
    if (next.stage === "confirm" || next.stage === "recovery") {
      return accept(await returningApi.authorize(signal), signal);
    }
    if (next.stage === "identify") {
      if (method.current === "passport") return accept(await returningApi.passport({}, signal), signal);
      if (method.current === "code") { setTransition({ stage: "passport" }); return; }
      const people = await returningApi.candidates(signal);
      if (signal.aborted) return;
      setCandidates(people);
      setTransition({ stage: people.narrowing_required || people.items.length === 0 ? "passport" : "identify" });
      return;
    }
    if (next.stage === "review") {
      const details = await returningApi.history(signal, groupToken.current);
      if (!signal.aborted) setHistory(details);
    }
    if (!signal.aborted) setTransition(next);
  };

  const sendOtp = async (signal: AbortSignal) => {
    const result = await returningApi.requestOtp(signal);
    if (!signal.aborted) { setResendAt(Date.now() + result.resend_after_seconds * 1000); setOtpSent(true); }
  };

  return {
    transition, candidates, history, pending, error, resendAt, otpSent,
    start: (body: ClaimStart) => run(async (signal) => {
      method.current = body.method;
      groupToken.current = body.group_token;
      await accept(await returningApi.start(body, signal), signal);
      if (body.method === "phone") await sendOtp(signal);
    }),
    requestOtp: () => run(sendOtp),
    verifyOtp: (code: string) => run(async (signal) => accept(await returningApi.verifyOtp(code, signal), signal)),
    select: (handle: string) => run(async (signal) => accept(await returningApi.selectCandidate(handle, signal), signal)),
    passport: (proof: PassportProof) => run(async (signal) => accept(await returningApi.passport(proof, signal), signal)),
    challenge: (answers: Partial<Record<DocumentQuestion, string>>) => run(async (signal) => accept(await returningApi.challenge(answers, signal), signal)),
    changeQuestion: (field: DocumentQuestion) => run(async (signal) => accept(await returningApi.changeQuestion(field, signal), signal)),
    confirm: (recover: boolean, actingFor: "self" | "family") => run(async (signal) => accept(await returningApi.confirm(recover, actingFor, signal), signal)),
    retryStage: () => run(async (signal) => { if (transition) await accept(transition, signal); }),
  };
}

"use client";

import { useEffect, useId, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useModalKeyboardBoundary } from "@/components/ui/modal";
import { normalizePhoneNumber, PHONE_FORMAT_HELP } from "@/lib/utils/phone-number";
import { returningApi } from "../api/returning.api";

export function ReturningContactDialog({ draftId, onClose, onSaved }: { draftId: string; onClose: () => void; onSaved: () => void }) {
  const [phone, setPhone] = useState("");
  const [code, setCode] = useState("");
  const [sent, setSent] = useState(false);
  const [verified, setVerified] = useState(false);
  const [confirmed, setConfirmed] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string>();
  const [resendAt, setResendAt] = useState(0);
  const [now, setNow] = useState(0);
  const operation = useRef<AbortController | null>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const titleId = useId();
  const keyboard = useModalKeyboardBoundary({ dialogRef, isOpen: true, canClose: !pending, onClose });
  useEffect(() => () => operation.current?.abort(), []);
  useEffect(() => { if (!resendAt) return; const timer = window.setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(timer); }, [resendAt]);
  const run = async (verify: boolean) => {
    if (operation.current) return;
    const controller = new AbortController(); operation.current = controller; setPending(true); setError(undefined);
    try {
      if (verify) {
        if (!verified) {
          await returningApi.verifyContact(code, draftId, controller.signal);
          if (!controller.signal.aborted) setVerified(true);
        }
        if (!controller.signal.aborted) onSaved();
      } else {
        const result = await returningApi.requestContact(normalizePhoneNumber(phone) ?? phone, draftId, controller.signal);
        if (!controller.signal.aborted) { setSent(true); setNow(Date.now()); setResendAt(Date.now() + result.resend_after_seconds * 1000); }
      }
    } catch (cause) { if (!controller.signal.aborted) setError(typeof cause === "object" && cause !== null && "message" in cause && typeof cause.message === "string" ? cause.message : "The contact change could not be confirmed. Retry when ready."); }
    finally { operation.current = null; if (!controller.signal.aborted) setPending(false); }
  };
  const resendIn = Math.max(0, Math.ceil((resendAt - now) / 1000));
  return <div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby={titleId} onKeyDown={keyboard} className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4">
    <form className="max-h-[90dvh] w-full max-w-md space-y-4 overflow-y-auto rounded-2xl bg-white p-5 shadow-xl" onSubmit={(event) => { event.preventDefault(); if (!sent || confirmed) void run(sent); }}>
      <h2 id={titleId} className="text-lg font-semibold text-slate-950">Change WhatsApp contact</h2>
      <p className="text-sm leading-6 text-slate-600">Verify your current WhatsApp number. It will be saved with your trip only when you select Submit on the review page.</p>
      <Input label="New WhatsApp number" value={phone} type="tel" autoComplete="tel" maxLength={64} required onChange={(event) => setPhone(event.target.value)} disabled={pending || sent} hint={PHONE_FORMAT_HELP} data-dialog-initial-focus className="h-12 text-base" />
      {sent && <><Input label="WhatsApp verification code" value={code} onChange={(event) => setCode(event.target.value.replace(/\D/g, ""))} inputMode="numeric" autoComplete="one-time-code" required minLength={6} maxLength={6} disabled={pending} className="h-12 text-base" /><Button type="button" variant="ghost" size="sm" disabled={pending || verified || resendIn > 0} onClick={() => void run(false)}>{resendIn ? `Resend available in ${resendIn}s` : "Resend code"}</Button><label className="flex items-start gap-3 text-sm leading-6 text-slate-700"><input type="checkbox" required checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} className="mt-1" />Use this verified number as this traveller’s current contact.</label></>}
      {error && <p role="alert" className="rounded-xl bg-red-50 p-3 text-sm text-red-800">{error}</p>}
      <div className="flex flex-wrap justify-end gap-2"><Button type="button" variant="secondary" onClick={onClose} disabled={pending}>Cancel</Button><Button type="submit" disabled={!normalizePhoneNumber(phone) || (sent && (!confirmed || code.length !== 6))} isLoading={pending}>{verified ? "Use verified contact" : sent ? "Verify for this draft" : "Send WhatsApp code"}</Button></div>
    </form>
  </div>;
}

"use client";

import { useEffect, useRef, useState } from "react";
import { ArrowLeft, LockKeyhole } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { UploadLinkResponse } from "@/features/passports/api/upload-links.api";
import { UploadHeader } from "@/features/upload/components/upload-flow-shell";
import { TravellerShell } from "@/features/upload/components/traveller-shell";
import { useReturningClaim } from "../hooks/use-returning-claim";
import type { CompletionResult, ReplacementRequest, ReturningCapabilities, ReturningMethod, ReturningOwnedSource } from "../types";
import { PassportProofFields } from "./returning-fields";
import { ReturningChallenge } from "./returning-challenge";
import { ReturningPhone } from "./returning-phone";
import { ReturningReview } from "./returning-review";

type Props = {
  token: string; group: UploadLinkResponse; initialMethod: ReturningMethod;
  capabilities: ReturningCapabilities; onFresh: () => void; onBack?: () => void;
  onReplace: (request: ReplacementRequest) => void; ownedSource?: ReturningOwnedSource;
  onCompleted?: (result: CompletionResult) => void;
};
const HEADINGS: Record<string, string> = {
  phone: "Verify your WhatsApp", passport: "Find your saved passport", code: "Enter your individual code",
  identify: "Choose the traveller", challenge: "One more check", confirm: "Opening your passport", recovery: "Opening your passport", review: "Opening your passport",
};

export function ReturningFlow({ token, group, initialMethod, capabilities, onFresh, onBack, onReplace, ownedSource, onCompleted }: Props) {
  const claim = useReturningClaim();
  const [passport, setPassport] = useState("");
  const [code, setCode] = useState("");
  const freshButton = useRef<HTMLButtonElement>(null);
  const stage = claim.transition?.stage;
  const failedProof = Boolean(claim.error && (stage === "challenge" || stage === "passport"));
  useEffect(() => { if (failedProof) freshButton.current?.focus({ preventScroll: true }); }, [failedProof]);
  if (stage === "review" && claim.history) return <ReturningReview history={claim.history} groupName={group.name} group={group} groupToken={token} onFresh={onFresh} onReplace={onReplace} ownedSource={ownedSource} onCompleted={onCompleted} />;
  const isPhone = initialMethod === "phone" && (!stage || stage === "contact");
  const headingKey = isPhone ? "phone" : stage || initialMethod;
  return <TravellerShell>
    <UploadHeader groupName={group.name} departureDate={group.travel_date} returnDate={group.return_date} />
    {onBack && <button type="button" disabled={claim.pending} onClick={onBack} className="mb-3 inline-flex min-h-11 items-center gap-2 text-sm font-medium text-slate-600 hover:text-blue-700"><ArrowLeft className="h-4 w-4" />Other verification options</button>}
    <section className="space-y-6 rounded-3xl border border-slate-200/80 bg-white p-5 shadow-[0_16px_50px_-30px_rgba(15,45,90,0.3)] sm:p-8" aria-busy={claim.pending}>
      <header>
        <span className="mb-4 flex h-11 w-11 items-center justify-center rounded-2xl bg-blue-50 text-blue-600"><LockKeyhole className="h-5 w-5" aria-hidden="true" /></span>
        <p className="text-xs font-semibold uppercase tracking-[0.14em] text-blue-600">Returning traveller</p>
        <h2 className="mt-2 text-2xl font-semibold tracking-tight text-slate-950">{HEADINGS[headingKey]}</h2>
        <p className="mt-2 text-sm leading-6 text-slate-500">{stage === "challenge" ? "Enter the date exactly as printed on your passport. We’ll check it with your passport number before opening your saved details." : "A quick verification keeps your saved travel documents private."}</p>
      </header>
      {claim.error && <div role="alert" className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm leading-6 text-red-800">{failedProof ? "We couldn’t verify a saved record with these details. Check your entries, try another verification option, or continue as a new traveller." : claim.error}</div>}
      {isPhone && <ReturningPhone started={stage === "contact"} pending={claim.pending} otpSent={claim.otpSent} resendAt={claim.resendAt} onStart={(phone) => void claim.start({ group_token: token, method: "phone", phone_number: phone })} onResend={() => void claim.requestOtp()} onVerify={(otp) => void claim.verifyOtp(otp)} />}
      {!stage && initialMethod !== "phone" && <form className="space-y-5" onSubmit={(event) => {
        event.preventDefault();
        void claim.start({ group_token: token, method: initialMethod, ...(initialMethod === "passport" ? { passport_number: passport } : { individual_code: code }) });
      }}>
        {initialMethod === "passport" ? <PassportProofFields number={passport} onNumber={setPassport} disabled={claim.pending} /> : <Input label={capabilities.code_label ?? "Agent / employee code"} value={code} onChange={(event) => setCode(event.target.value)} maxLength={128} required autoComplete="off" disabled={claim.pending} hint="Use your individual code, including any leading zeros." className="h-12 text-base" />}
        <Button type="submit" className="min-h-12 w-full" isLoading={claim.pending}>Continue</Button>
      </form>}
      {stage === "identify" && claim.candidates && <div className="space-y-3"><p className="text-sm leading-6 text-slate-600">Select your record, then confirm the full passport number.</p><ul className="space-y-2">{claim.candidates.items.map((person) => <li key={person.handle}><Button type="button" variant="secondary" className="h-auto min-h-12 w-full justify-between whitespace-normal py-3 text-left" disabled={claim.pending} onClick={() => void claim.select(person.handle)}><span>{person.label}</span><span className="text-xs text-slate-500">{person.passport_hint}</span></Button></li>)}</ul></div>}
      {stage === "passport" && <form className="space-y-5" onSubmit={(event) => { event.preventDefault(); void claim.passport({ passport_number: passport }); }}><PassportProofFields number={passport} onNumber={setPassport} disabled={claim.pending} /><Button type="submit" isLoading={claim.pending} className="min-h-12 w-full">Verify passport</Button></form>}
      {stage === "challenge" && claim.transition && <ReturningChallenge transition={claim.transition} pending={claim.pending} onVerify={(answers) => void claim.challenge(answers)} onChangeQuestion={(field) => void claim.changeQuestion(field)} />}
      {((stage === "identify" && !claim.candidates) || stage === "confirm" || stage === "recovery" || stage === "review") && <Button type="button" className="min-h-12 w-full" isLoading={claim.pending} onClick={() => void claim.retryStage()}>Load verified details</Button>}
      <div className="border-t border-slate-100 pt-5"><Button ref={freshButton} type="button" variant={failedProof ? "secondary" : "ghost"} className={`h-auto min-h-12 w-full whitespace-normal ${failedProof ? "border-blue-400 bg-blue-50 text-blue-700 ring-2 ring-blue-100" : ""}`} onClick={onFresh} disabled={claim.pending}>Continue as a new traveller</Button></div>
    </section>
  </TravellerShell>;
}

"use client";

import { useEffect, useRef, useState } from "react";
import { ArrowRight, FileCheck2, MessageCircle, BadgeCheck, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useReturningCapabilities } from "../hooks/use-returning-capabilities";
import type { ReturningCapabilities, ReturningMethod } from "../types";

export function ReturningTravellerOffer({ token, onSelect, onFresh }: { token: string; onSelect: (method: ReturningMethod, capabilities: ReturningCapabilities) => void; onFresh?: () => void }) {
  const capabilities = useReturningCapabilities(token);
  const [pending, setPending] = useState<ReturningMethod | null>(null), [notice, setNotice] = useState<string>();
  const selection = useRef<symbol | null>(null);
  useEffect(() => () => { selection.current = null; }, [token]);
  const select = async (method: ReturningMethod) => {
    if (selection.current) return;
    const request = Symbol(); selection.current = request; setPending(method); setNotice(undefined);
    const result = capabilities.data ?? (await capabilities.refetch({ cancelRefetch: false })).data;
    if (selection.current !== request) return;
    selection.current = null; setPending(null);
    if (!result?.enabled) return;
    if (method === "code" && !result.code_label) { setNotice("Code verification is not enabled for this trip. Choose WhatsApp OTP or passport number."); return; }
    onSelect(method, result);
  };
  if (capabilities.data?.enabled === false) return <section className="rounded-3xl border border-slate-200 bg-white p-6 text-sm text-slate-600" aria-live="polite">
    <h2 className="text-lg font-semibold text-slate-900">Upload documents for this trip</h2><p className="mt-2 leading-6">Saved-document access is not available for this link. You can continue with a fresh submission.</p>{onFresh && <Button className="mt-5 w-full" onClick={onFresh}>Continue as a new traveller</Button>}
  </section>;
  const options = [
    { method: "phone" as const, label: "WhatsApp OTP", detail: "Use your saved WhatsApp number.", icon: MessageCircle },
    { method: "passport" as const, label: "Passport number", detail: "Verify with a detail from your passport.", icon: FileCheck2 },
    ...(!capabilities.data || capabilities.data.code_label ? [{ method: "code" as const, label: "Agent / employee code", detail: "Use your individual code and passport number.", icon: BadgeCheck }] : []),
  ];
  return <section aria-label="Returning traveller" className="rounded-3xl border border-slate-200/80 bg-white p-5 shadow-[0_12px_48px_-24px_rgba(15,45,90,0.28)] sm:p-8">
    <p className="text-xs font-semibold uppercase tracking-[0.16em] text-blue-600">Welcome back</p>
    <h2 className="mt-2 text-2xl font-semibold tracking-tight text-slate-950">Find your saved passport</h2>
    <p className="mt-2 text-sm leading-6 text-slate-500">Choose a way to verify your details securely.</p>
    {capabilities.isError && !capabilities.data && <div role="alert" className="mt-4 rounded-xl bg-red-50 p-4 text-sm text-red-700">We couldn’t connect. Select your preferred option to try again.</div>}
    {notice && <p role="status" className="mt-4 text-sm text-slate-600">{notice}</p>}
    <div className="mt-6 grid gap-3">{options.map(({ method, label, detail, icon: Icon }) => <button key={method} type="button" disabled={pending !== null} aria-busy={pending === method} onClick={() => void select(method)} className="group flex min-h-20 items-center gap-3 rounded-2xl border border-slate-200 px-4 py-4 text-left transition-colors hover:border-blue-400 hover:bg-blue-50/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 disabled:cursor-wait"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-blue-50 text-blue-600"><Icon className="h-5 w-5" aria-hidden="true" /></span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold text-slate-900">{label}</span><span className="mt-1 block text-xs leading-5 text-slate-500">{pending === method ? "Opening verification…" : detail}</span></span>{pending === method ? <Loader2 className="h-4 w-4 shrink-0 animate-spin text-blue-600" aria-hidden="true" /> : <ArrowRight className="h-4 w-4 shrink-0 text-slate-400 group-hover:text-blue-600" aria-hidden="true" />}</button>)}</div>
    {onFresh && <div className="mt-6 border-t border-slate-100 pt-4"><Button variant="ghost" className="w-full" onClick={onFresh}>Continue as a new traveller</Button></div>}
  </section>;
}

"use client";
import { useEffect, useState } from "react";
import { returningApi } from "../api/returning.api";
import type { ReturningHistory } from "../types";
import { ReturningReview } from "./returning-review";
import { TravellerShell } from "@/features/upload/components/traveller-shell";
import { Button } from "@/components/ui/button";
import { BrandLogo } from "@/components/brand/brand-logo";
import type { UploadLinkResponse } from "@/features/passports/api/upload-links.api";

export function ReturningResume({ token, groupName, group, onFresh, onVerify }: { token: string; groupName: string; group?: UploadLinkResponse; onFresh: () => void; onVerify: () => void }) {
  const [history, setHistory] = useState<ReturningHistory>();
  const [verificationNeeded, setVerificationNeeded] = useState(false);
  useEffect(() => {
    const controller = new AbortController();
    void returningApi.history(controller.signal, token).then((result) => { if (!controller.signal.aborted) setHistory(result); })
      .catch(() => { if (!controller.signal.aborted) setVerificationNeeded(true); });
    return () => controller.abort();
  }, [token]);
  if (history) return <ReturningReview history={history} groupName={groupName} group={group} groupToken={token} onFresh={onFresh} onReplace={onFresh} />;
  return <TravellerShell><BrandLogo className="mx-auto mb-6" priority /><section className="space-y-4 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
    <h1 className="text-2xl font-semibold text-slate-950">Continue your saved draft</h1>
    {verificationNeeded ? <><p className="text-sm leading-6 text-slate-500">Your temporary draft stays saved for 24 hours. Verify your passport again to reopen your private details and continue.</p><Button type="button" className="min-h-12 w-full" onClick={onVerify}>Verify and continue</Button></> : <p role="status" className="text-sm text-slate-500">Opening your secure draft…</p>}
  </section></TravellerShell>;
}

"use client";

import { useEffect, useRef, useState } from "react";
import { CheckCircle2, Clock3, MessageCircle, RefreshCw, Upload } from "lucide-react";
import { Button } from "@/components/ui/button";
import { BrandLogo } from "@/components/brand/brand-logo";
import { CustomDetailFields, CustomQuestionFields } from "@/features/upload/components/upload-flow-fields";
import { ReviewFields } from "@/features/upload/components/upload-flow-review";
import { TravellerShell } from "@/features/upload/components/traveller-shell";
import { ReviewDetailsColumn } from "@/features/upload/components/review-details-column";
import type { UploadLinkResponse } from "@/features/passports/api/upload-links.api";
import { useReturningDraft } from "../hooks/use-returning-draft";
import { returningApi } from "../api/returning.api";
import type { CompletionResult, ReplacementRequest, ReturningHistory, ReturningOwnedSource } from "../types";
import { ReturningContactDialog } from "./returning-contact-dialog";
import { ReturningCurrentDetails } from "./returning-current-details";
import { ReturningDraftImages } from "./returning-draft-images";
import { ReturningCollection } from "./returning-collection";
import { draftReviewReadiness } from "../services/draft-readiness";

type Props = { history: ReturningHistory; groupName: string; group?: UploadLinkResponse; groupToken?: string; onFresh: () => void; onReplace: (request: ReplacementRequest) => void; ownedSource?: ReturningOwnedSource; onCompleted?: (result: CompletionResult) => void };

export function ReturningReview(props: Props) {
  const [history, setHistory] = useState(props.history);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState<string>();
  const operation = useRef<AbortController | null>(null);
  useEffect(() => () => operation.current?.abort(), []);
  const reload = async (passportId?: string) => {
    if (operation.current) return;
    const controller = new AbortController(); operation.current = controller; setLoading(true); setLoadError(undefined);
    try {
      const result = passportId ? await returningApi.selectPassport(passportId, controller.signal, props.groupToken) : await returningApi.history(controller.signal, props.groupToken);
      if (!controller.signal.aborted) setHistory(result);
    } catch { if (!controller.signal.aborted) setLoadError("The latest details could not be loaded. Your draft is still saved; please retry."); }
    finally { operation.current = null; if (!controller.signal.aborted) setLoading(false); }
  };
  return <ReturningReviewContent key={history.review_version} {...props} history={history} loading={loading} loadError={loadError} reload={reload} />;
}

function ReturningReviewContent({ history, groupName, group, groupToken = "", ownedSource, onFresh, onCompleted, loading, loadError, reload }: Props & { loading: boolean; loadError?: string; reload: (id?: string) => Promise<void> }) {
  const form = useReturningDraft(history, groupToken, ownedSource);
  const [replacement, setReplacement] = useState(false);
  const [contactOpen, setContactOpen] = useState(false);
  const [confirmed, setConfirmed] = useState(false);
  const [uploadBusy, setUploadBusy] = useState(false);
  const [result, setResult] = useState<CompletionResult>();
  const draft = form.draft;
  const payload = form.payload;
  const displayName = [payload?.passport_fields.given_names, payload?.passport_fields.surname].filter(Boolean).join(" ") || history.display_name;
  const { extracting, contact, needsContact, needsReplacement, needsBack, canSubmit } = draftReviewReadiness(history, draft, form.pending, confirmed, group);
  const photoRequired = (history.missing_requirements ?? []).some((key) => key === "fresh_photo" || key === "visa_photo");
  const qualifierRequired = (history.missing_requirements ?? []).includes("qualifier_relationship");
