        <div className="flex flex-col gap-4 border-t border-slate-100 pt-4 sm:flex-row sm:items-center sm:justify-between"><p role="status" className="flex items-start gap-2 text-xs leading-5 text-slate-500"><Clock3 className="mt-0.5 h-4 w-4 shrink-0" /><span>{form.dirty ? "Saving your details…" : "Details saved for 24 hours."}<br />Unsubmitted images are not kept when you leave. Your official record updates only after submission.</span></p><Button type="submit" className="min-h-12 px-6" disabled={!canSubmit || uploadBusy} isLoading={form.pending}>Submit trip details</Button></div>
      </section>
    </form>}
    {contactOpen && draft && <ReturningContactDialog draftId={draft.id} onClose={() => setContactOpen(false)} onSaved={() => { setConfirmed(false); setContactOpen(false); void form.refresh().catch(() => undefined); }} />}
  </TravellerShell>;
}

